// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// A flow that answered the visitor is recorded (resolution rate and rating
// per flow). No ticket.
import type { PathEntry } from "./flow-engine";

export interface WidgetEndpoint {
  apiBase: string;
  widgetKey: string;
  sessionToken: string | null;
}

// The outcome's id, or null when it could not be recorded (the chat goes on
// regardless: the visitor already has their answer).
export async function postFlowOutcome(endpoint: WidgetEndpoint, path: PathEntry[]): Promise<string | null> {
  try {
    const res = await fetch(`${endpoint.apiBase}/widget_api/v1/flow_outcomes`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Widget-Key": endpoint.widgetKey },
      body: JSON.stringify({
        ...(endpoint.sessionToken ? { session_token: endpoint.sessionToken } : {}),
        path,
        outcome: "resolved",
      }),
    });
    if (!res.ok) return null;
    const data = await res.json();
    return typeof data?.id === "string" ? data.id : null;
  } catch {
    return null;
  }
}

export async function rateFlowOutcome(endpoint: WidgetEndpoint, id: string, rating: number): Promise<void> {
  try {
    await fetch(`${endpoint.apiBase}/widget_api/v1/flow_outcomes/${encodeURIComponent(id)}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "X-Widget-Key": endpoint.widgetKey },
      body: JSON.stringify({ rating }),
    });
  } catch {
    // The rating is a bonus: a failure is not worth bothering the visitor.
  }
}
